from collections import Counter
def f(g, orient='row'):
    h=len(g); w=len(g[0])
    # candidate separators: rows/cols dominated by a color != global fill, appearing as isolated lines
    if orient=='row':
        lines=[]
        for r in range(h):
            cnt=Counter(g[r])
            d=cnt.most_common(1)[0]
            if d[0]!=5 and d[1]>=w*0.6: lines.append((r,d[0]))
        fill=Counter(v for row in g for v in row).most_common(1)[0][0]
        SRS=[r for r,_ in lines]; LC={r:_ for r,_ in lines}
        # marked vlines: columns where some separator has anomalous value (not LC value of that column -> use dominant of column over pattern rows)
        Mset=set()
        for c in range(w):
            pv=[g[r][c] for r in range(h) if r not in SRS]
            cc=Counter(pv).most_common(1)[0][0]
            if any(g[r][c]!=cc for r in SRS): Mset.add(c)
        Ms=sorted(Mset)
        O=[[LC[SRS[i]]]*(len(Ms)-1) for _ in range(len(SRS)-1)]
        for i in range(len(SRS)-1):
            for j in range(len(Ms)-1):
                vals=[g[SRS[i]][Ms[j]],g[SRS[i+1]][Ms[j]],g[SRS[i]][Ms[j+1]],g[SRS[i+1]][Ms[j+1]]]
                if len(set(vals))==1 and vals[0]!=CC(g,SRS,Ms,i,j): O[i][j]=vals[0]
        return O
