def solve(g):
    h=len(g); w=len(g[0])
    cnt=Counter(v for row in g for v in row)
    dom=cnt.most_common(1)[0][0]
    # separator color: the non-dom color forming most common row/col lines; try candidates
    best=None
    for v,n in cnt.items():
        if v==dom: continue
        rs=sum(1 for r in range(h) if sum(1 for x in g[r] if x==v)>=w*0.4)
        cs=sum(1 for c in range(w) if sum(1 for r in range(h) if g[r][c]==v)>=h*0.4)
        score=rs+cs
        if best is None or score>best[0]: best=(score,v)
    sepc=best[1]
    srs=[r for r in range(h) if sum(1 for x in g[r] if x==sepc)>=w*0.5]
    scs=[c for c in range(w) if sum(1 for r in range(h) if g[r][c]==sepc)>=h*0.5]
    def bands(seps,n):
        bs=[]; prev=None
        for s in seps+[n]:
            if prev is not None and s>prev+1: bs.append((prev+1,s-1))
            prev=s
        return bs
    RB=bands(srs,h); CB=bands(scs,w)
    out=[[dom]*len(CB) for _ in RB]
    # group anomalies by color into maximal rectangles (min/max row & col among cells of that color)
    pos={}
    for r in range(h):
        for c in range(w):
            if g[r][c]!=dom and g[r][c]!=sepc: pos.setdefault(g[r][c],[]).append((r,c))
    for col,cells in pos.items():
        rs=[a for a,b in cells]; cs=[b for a,b in cells]
        r1,r2,c1,c2=min(rs),max(rs),min(cs),max(cs)
        for i,(r0,r1b) in enumerate(RB):
            for j,(c0,c1b) in enumerate(CB):
                if r0>=r1 and r1b<=r2 and c0>=c1 and c1b<=c2:
                    out[i][j]=col
    return out
